Translate("ruRU", "skywall", {
	title = "Небесная Высь",
	aliases = { "царство воздуха", "план воздуха" },
	sections = {
		{
			title = "Обзор",
			text = [=[Небесная Высь — царство воздуха, один из четырех уделов Стихийного плана. Это бескрайнее небо бурь и воздушных течений, под которым нет земли и над которым нет свода. Ее хозяин — {link:al-akir}Ал'Акир{/link}, Владыка Ветра, а ее исконные дети — духи и элементали ветра. Для большинства народов {link:azeroth}Азерота{/link} Небесная Высь — лишь слово из преданий шаманов. Для народа {link:skyborne}Рожденных Небом{/link} она уже десять тысяч лет служит домом.]=],
		},
		{
			title = "Истоки",
			text = [=[Некогда повелители стихий бушевали по всему юному миру. В первую эпоху они служили Древним богам, а когда слуги титанов сокрушили ту темную империю, элементали были изгнаны из мира и заточены в особом царстве. Каждому повелителю достался свой удел. Воздух выпал на долю {link:al-akir}Ал'Акир{/link}а. С тех пор ветер Небесной Выси дует там, куда не достигает взор смертных, и немногие из вошедших туда вернулись, чтобы рассказать о ней.]=],
		},
		{
			title = "Сокрытые острова",
			text = [=[В долгие века после {link:war-of-the-ancients}Войны древних{/link} эльфы, бежавшие из Эльдре'Таласа, нашли приют в Небесной Выси. Духи ветра подняли их землю в небо и поместили ее в тихом уголке царства, куда не падал взор Владыки Ветра. Там {link:skyborne}шен'дорай{/link} основали россыпь островных провинций. Одной из них был {link:zephras-isle}остров Зефрас{/link}. Другими были Анвилас и Сироккас с их городами Шен'драмаром и Новым Элдре'нааром. Когда-то потоки ветра, называемые небесными течениями, переносили путников с острова на остров. Эти дороги давно закрыты.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:the-harborage}Убежище{/link} перестало быть убежищем. Духи, охранявшие острова, давно исчезли, а {link:anchor-pylons}якорные пилоны{/link}, что удерживали {link:zephras-isle}Зефрас{/link} на месте, были и оберегами, скрывавшими его. Эти обереги пали. Один из владык восточного ветра увидел остров своими глазами и пообещал, что {link:al-akir}Ал'Акир{/link} услышит о нем. Никто из {link:skyborne}шен'дорай{/link} не может сказать, когда Владыка Ветра обратит на них взор. Но все они знают, что это случится.]=],
		},
	},
})

Translate("ruRU", "zephras-isle", {
	title = "остров Зефрас",
	aliases = { "Зефрас" },
	sections = {
		{
			title = "Обзор",
			text = [=[Остров Зефрас парит в {link:skywall}Небесной Выси{/link}, царстве воздуха, вдали от всех берегов {link:azeroth}Азерота{/link}. Это дом народа {link:skyborne}Рожденных Небом{/link} — эльфов, которые называют себя шен'дорай. Над его северными рощами высятся {link:ogres}огр{/link}омные деревья, середину острова занимают синие холмистые нагорья, а на юго-восточном краю стоит порт {link:valanaar}Валанаар{/link}. С его утесов водопады срываются прямо в открытое небо. Десять тысяч лет остров был тайным убежищем. Теперь он разрушается, и его народ начал смотреть вниз — на мир, из которого бежали его предки.]=],
		},
		{
			title = "Истоки",
			text = [=[Шен'дорай происходят от мятежников Эльдре'Таласа — города высокорожденных в {link:feralas}Фераласе{/link}, который ныне зовется {red:dire-maul}Забытым Городом{/red}. Они восстали против принца {red:tortheldrin}Тортелдрина{/red}, проиграли свою войну и бежали на запад через море. Когда корабли принца стали их настигать, {link:vanishing-of-the-wind-spirits}духи ветра{/link} подняли в небо {link:ogres}огр{/link}омный кусок земли и унесли его прочь из мира. Они закрепили его в Небесной Выси древними пилонами, и там изгнанники создали среди облаков малую, но светлую цивилизацию. Ее основатель, мятежник в маске по прозванию {link:flight-from-eldre-thalas}Шал'нан{/link}, позже передал свою власть совету, избранному народом.]=],
		},
		{
			title = "Наши дни",
			text = [=[Несколько веков назад {link:vanishing-of-the-wind-spirits}духи ветра{/link} исчезли, не сказав ни слова. С тех пор пилоны слабеют, и целые округа осыпались в небо. Селение {link:ruins-of-ban-aethal}Бан'этал{/link} рухнуло за одну ночь. Связь с другими островами {link:skyborne}шен'дорай{/link} утрачена, а беженцы, добравшиеся до Зефраса, теснятся в {link:valanaar}Валанаар{/link}е или уходят в разбойники. В этот страх пришли {link:al-aketh}Ал'Акет{/link} — культ, поклоняющийся {link:al-akir}Ал'Акиру{/link}, во главе с Верховной жрицей Лортуной. Они захватили деревню Фалаат и {link:shrine-of-akir}Святилище Акира{/link} и ударили по сторожевым башням у пилонов. Их целью было сломать обереги, скрывавшие остров. {link:windshapers}Ваятели Ветра{/link} и {link:high-order}Высший орден{/link} презирают друг друга, но они встали рядом с {link:peacekeepers}Миротворцами{/link}, которыми командует {link:valennia-stormfist}Валенния Кулак Бури{/link}, против культа, и культ был разбит. Дело его разбито не было. Оберегов больше нет, и один из владык воинства Владыки Ветра видел Зефрас. Теперь каждый орден отправляет своих юных в {link:azeroth}Азерот{/link}: Ваятели Ветра — к {link:earthen-ring}Служителям Земли{/link} в {link:mulgore}Мулгор{/link}, Высший орден — к {link:kirin-tor}Кирин-Тору{/link} в {link:dalaran}Даларан{/link}.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:shadow-council}Совет{/link} старейшин.{/b} Верховный старейшина {link:talaanis-shadowsong}Талаанис Песнь Теней{/link} возглавляет совет острова из {link:valanaar}Валанаар{/link}а.
• {b}{link:windshapers}Ваятели Ветра{/link}.{/b} Шаманы и провидцы, которые охраняют священные камни и ищут пропавших духов.
• {b}{link:high-order}Высший орден{/link}.{/b} Магистры крови высокорожденных, которые хотят сами овладеть магией острова.
• {b}{link:peacekeepers}Миротворцы{/link}.{/b} Ополчение острова — самое близкое к войску, что есть у {link:skyborne}шен'дорай{/link}.
• {b}{link:al-aketh}Ал'Акет{/link}.{/b} Фанатики Владыки Ветра, рассеянные, но не уничтоженные.
• {b}Ночной Коготь.{/b} Скрытный круг друидов в лесу Теневого Шквала.
• {b}Звери.{/b} Вулдрены, урсеры, гордокогти, гипп{link:ogres}огр{/link}ифы и крикуны; многие одичали с тех пор, как умолкли ветра.]=],
		},
		{
			title = "Предания острова",
			text = [=[• Шен'дорай, достигший совершеннолетия, получает наследную реликвию, которую прежде носил кто-то из его предшественников. Когда ее владелец умирает, реликвию возвращают для следующего юноши или девушки.
• Мертвых сжигают, а их прах отдают ветрам.
• Камни ветра — синие самоцветы, полные необузданного ветра, — теперь освещают и с{link:ogres}огр{/link}евают большинство домов острова.
• Малые кристаллы памяти хранят голоса. Стоит коснуться такого кристалла, и запись едва слышно разносится по воздуху.]=],
		},
	},
})

Translate("ruRU", "thendal-village", {
	title = "деревня Тендал",
	aliases = { "Роща Тендал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Тендал лежит в северных рощах {link:zephras-isle}Зефрас{/link}а, где юные {link:skyborne}шен'дорай{/link} достигают совершеннолетия. Ее дома построены внутри и вокруг исполинского дерева-прадеда, а ее следопыты хранят равновесие леса. Селением руководит {link:rorian-the-dayseeker}Рориан Искатель Дня{/link}. Старейшины совета приходят сюда, чтобы оценить юных и отправить их в путь по острову. К востоку от селения стоят Стоячие камни Тендала — место ветра и силовых линий. Вверх по перевалу на северо-востоке лежит Холм Духов, где послушники Ваятелей Ветра пьют священный напиток сапта. В пещере на юге устроили логово урсеры. В последнее время культ добрался даже сюда.]=],
		},
	},
})

Translate("ruRU", "shen-dar-village", {
	title = "деревня Шен'дар",
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Шен'дар — первое селение к югу от северных рощ, стоящее среди синих холмов Нагорья Шен'дар. Покой в нем хранит констебль {link:constable-aonda}Аонда{/link}, у которой слишком мало бойцов. У обоих орденов здесь есть свои старейшины: {link:illaya-amberwind}Иллайя Янтарный Ветер{/link} от Ваятелей Ветра и {link:rathiril-sunlance}Ратирил Солнечное Копье{/link} от Высшего ордена, и согласны они мало в чем. Постоялый двор держит Кориэлла Тихий Бриз. Какое-то время селение терпело на своих улицах проповедницу {link:al-aketh}Ал'Акет{/link}. Этот мир кончился, когда культ собрался в Фалаате, чтобы ударить по селению, и жители ударили первыми.]=],
		},
	},
})

Translate("ruRU", "shen-dar-highlands", {
	title = "Нагорье Шен'дар",
	sections = {
		{
			title = "Обзор",
			text = [=[Нагорье Шен'дар — холмистое сердце {link:zephras-isle}Зефрас{/link}а. Здешние стоячие камни священны для ордена {link:windshapers}Ваятелей Ветра{/link}, который стережет их от любопытных магистров {link:high-order}Высшего ордена{/link}. У этих камней между двумя орденами уже пролилась кровь. На севере, в пещере за водопадом, прячутся разбойники, на юге гнездятся гипп{link:ogres}огр{/link}ифы, а гордокогти рыщут у самого селения. На холме близ нагорного пилона живет Курамаа — проказливый старый лесной дух. В холмах охотится Вулгара из крылатых вулдренов, и {link:peacekeepers}Миротворцы{/link} назначили награду за ее голову.]=],
		},
	},
})

Translate("ruRU", "falaath-village", {
	title = "деревня Фалаат",
	sections = {
		{
			title = "Обзор",
			text = [=[Деревня Фалаат лежит в руинах среди Нагорья Шен'дар, и {link:al-aketh}Ал'Акет{/link} сделали ее своей. У ее ворот проповедники принимают новообращенных и отмечают их знаком Акира. Среди разрушенных домов рождаются бури, которые призывают заклинатели бурь культа. Именно на постоялом дворе Фалаата небесный жрец {link:skypriest-aanders}Аандерс{/link} тайно принимал Верховную жрицу Лортуну, и там культ задумал свой двойной удар — по деревне Шен'дар и по западной сторожевой башне. Первый должен был возглавить командир Циклас. Он не дожил до этого.]=],
		},
	},
})

Translate("ruRU", "windsong-lake", {
	title = "озеро Песни Ветра",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Песни Ветра лежит в середине {link:zephras-isle}Зефрас{/link}а, между нагорьями и святилищем. На его берегах и в питающих его реках живут крабы, которых зовут ползунами Песни Ветра, и больше их нет нигде в мире. Ловить их можно лишь несколько недель в году. Когда-то эти крабы были лакомством, которое возили на другие острова {link:skyborne}шен'дорай{/link}. Прежде озеро бороздили конструкты, подаренные духами ветра. Когда пилоны начали слабеть, многие из них ушли на дно, и некоторые лежат там по сей день.]=],
		},
	},
})

Translate("ruRU", "west-pylon-watchtower", {
	title = "Сторожевая башня Западного пилона",
	aliases = { "западная сторожевая башня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожевая башня Западного пилона охраняет один из якорных пилонов на юго-западном краю Нагорья Шен'дар. Башню держали {link:peacekeepers}Миротворцы{/link}, пока не пришли {link:al-aketh}Ал'Акет{/link}. Нападением руководил небесный жрец {link:skypriest-aanders}Аандерс{/link}, и защитники погибли на своем посту. Среди них был племянник Верховного старейшины Талааниса Песнь Теней; его родовой перстень-печатку нашли у башни. Что небесный жрец сделал там с пилоном, не записано. {link:shadow-council}Совет{/link} знал лишь одно: культ пришел за башней, а не за солдатами в ней.]=],
		},
	},
})

Translate("ruRU", "valanaar", {
	title = "Валанаар",
	sections = {
		{
			title = "Обзор",
			text = [=[Валанаар — порт и главный город острова {link:zephras-isle}Зефрас{/link}, построенный на юго-восточном краю острова. Здесь держит совет Верховный старейшина {link:talaanis-shadowsong}Талаанис Песнь Теней{/link}, и из того же зала {link:valennia-stormfist}Валенния Кулак Бури{/link} командует отрядами Миротворцев. {link:windshapers}Ваятели Ветра{/link} держат обитель близ центра города, а {link:high-order}Высший орден{/link} — другую, на его дальней юго-восточной стороне. Капитан запрещает им открытую вражду на своих улицах. Беженцы из {link:ruins-of-ban-aethal}Бан'этал{/link}а ждут в городе вестей. Из Небесных доков Валанаара небесные корабли теперь ходят через планы в {link:azeroth}Азерот{/link}: один — в {link:mulgore}Мулгор{/link}, другой — в {link:dalaran}Даларан{/link}.]=],
		},
	},
})

Translate("ruRU", "gustberry-lowlands", {
	title = "Низины Ветроягоды",
	aliases = { "Поля Ветроягоды" },
	sections = {
		{
			title = "Обзор",
			text = [=[Низины Ветроягоды — возделанные земли вокруг {link:valanaar}Валанаар{/link}а, богатые садами и открытыми полями. Над ними парят гигантские порхокрылы, а вихреходы разоряют урожай. Разбойники с большой дороги держат в холмах небольшие лагеря. Крикуны из пещеры к западу от города осмелели, и один ученый Высшего ордена едва не погиб среди них. Когда {link:al-aketh}Ал'Акет{/link} двинулись на восточный пилон, низины стали полем боя, и целители и бойцы культа заполнили поля к северу от города. На краю острова к западу от Валанаара {link:windshapers}Ваятели Ветра{/link} хранят тайное Святилище Пламени.]=],
		},
	},
})

Translate("ruRU", "east-pylon-watchtower", {
	title = "Сторожевая башня Восточного пилона",
	aliases = { "восточная сторожевая башня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожевая башня Восточного пилона стоит у самого {link:valanaar}Валанаар{/link}а и охраняет ближайший к городу {link:anchor-pylons}якорный пилон{/link}. {link:al-aketh}Ал'Акет{/link} напали на нее большими силами под началом командира {link:commander-belguilos}Белгилос{/link} — бывшей воительницы Миротворцев, которую культ зовет Сокрушительницей. {link:yorana-windyreed}Йорана Ветреный Тростник{/link} привела из города отряд на выручку и удержала башню, хотя и ждала, что погибнет там. Когда Белгилос пала, натиск захлебнулся. {link:shadow-council}Совет{/link} увидел, что культ ударил и по западной, и по восточной башне, и понял наконец, что его целью были сами пилоны.]=],
		},
	},
})

Translate("ruRU", "windfield-orchard", {
	title = "Сад Ветреного Поля",
	sections = {
		{
			title = "Обзор",
			text = [=[В Саду Ветреного Поля, в низинах к западу от {link:valanaar}Валанаар{/link}а, растут грозовые яблоки. Сад принадлежит супругам Алвариону и Аамелии Ветреное Поле. Шайка разбойников, которой верховодит Ферауу Дубина, силой забирала долю каждого урожая. Когда Алварион был тяжело ранен, он отправился в город нанимать помощь, а его жена осталась защищать деревья. В саду стоит и старый конструкт-вихрь духов ветра, сломанный и бормочущий. Он снова и снова задает один и тот же вопрос: в чем его предназначение?]=],
		},
	},
})

Translate("ruRU", "shrine-of-akir", {
	title = "Святилище Акира",
	sections = {
		{
			title = "Обзор",
			text = [=[Святилище Акира возвышается к северу от {link:valanaar}Валанаар{/link}а, над полями и водопадами восточной части острова. Это оплот {link:al-aketh}Ал'Акет{/link} и престол Верховной жрицы Лортуны. Сюда пришел говорить о мире магистр Высшего ордена {link:belathaan-brightwish}Белатаан Светлое Желание{/link}, и здесь он погиб. Сюда же {link:valennia-stormfist}Валенния Кулак Бури{/link} повела на приступ Миротворцев, Ваятелей Ветра и {link:high-order}Высший орден{/link}. Ее бойцы ударили в лоб, а сама она провела ордена вверх по флангу, во внутреннее святилище. С обеих сторон пали многие. {link:high-priestess-lorthuna}Лортуна{/link} бежала через портал на шпили наверху.]=],
		},
	},
})

Translate("ruRU", "rohashi-spires", {
	title = "шпили Рохаши",
	sections = {
		{
			title = "Обзор",
			text = [=[Шпили {link:rohash}Рохаш{/link}и парят в открытом небе над Святилищем Акира, и попасть на них можно лишь через портал из святилища. Здесь {link:high-priestess-lorthuna}Лортуна{/link} приняла свой последний бой. Она пришла не затем, чтобы сломать обереги: они уже были сломаны. Она пришла зажечь маяк. На него откликнулся Рохаш, Владыка Восточного Ветра. Мгновение эльфы стояли одни против воинства Владыки Ветра. Затем через портал пришли шаманы {link:earthen-ring}Служителей Земли{/link} и маги {link:kirin-tor}Кирин-Тора{/link}, и шпили стали местом, где {link:skyborne}Рожденные Небом{/link} впервые встретили своих новых союзников.]=],
		},
	},
})

Translate("ruRU", "shadowgale-forest", {
	title = "лес Теневого Шквала",
	aliases = { "Теневой Шквал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лес Теневого Шквала покрывает северо-восток {link:zephras-isle}Зефрас{/link}а, и большинство {link:skyborne}шен'дорай{/link} верит, что в нем водятся призраки. Они не ошибаются. Между его деревьями плывут бледные {link:vanishing-of-the-wind-spirits}духи ветра{/link}, которых зовут пустыми; впервые они появились после того, как исчезли духи ветра. Культ обычно сторонится этого леса, и здешние друиды охотно питают этот страх. В пещере на северо-востоке держат свое логово друиды Ночного Когтя. {link:al-aketh}Ал'Акет{/link} обрушились на него без предупреждения, а привел их один из самих друидов. Среди деревьев живет и отшельник, который годами ни с кем не говорил.]=],
		},
	},
})

Translate("ruRU", "ruins-of-ban-aethal", {
	title = "Руины Бан'этала",
	aliases = { "Бан'этал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Бан'этал был селением в глубине леса Теневого Шквала, на северо-восточном краю острова. Однажды ночью, без всякого предупреждения, земля под ним начала падать в небо. Его жители бежали с тем, что смогли унести, и теперь ждут в {link:valanaar}Валанаар{/link}е. Некоторые вернулись за своим добром и не пришли назад. Среди руин собираются призрачные духи и поют странную и скорбную песнь, словно они привязаны к этому месту. Говорят, что там спит великий дракон стихий.]=],
		},
	},
})

Translate("ruRU", "talaanis-shadowsong", {
	title = "Талаанис Песнь Теней",
	subtitle = "Верховный старейшина острова Зефрас",
