	sections = {
		{
			title = "Обзор",
			text = [=[Талаанис Песнь Теней — Верховный старейшина острова {link:zephras-isle}Зефрас{/link} и глава его {link:shadow-council}Совет{/link}а старейшин. Он правит из {link:valanaar}Валанаар{/link}а, бок о бок с капитаном Миротворцев. Он не принадлежит ни к {link:windshapers}Ваятелям Ветра{/link}, ни к {link:high-order}Высшему ордену{/link}, и ему приходится удерживать вместе народ, готовый разорвать себя на части. Те, кто ему служит, называют его достойным мужем. Даже в эти тяжелые годы жители острова любят его.]=],
		},
		{
			title = "Значение",
			text = [=[Талаанис стоит во главе старого порядка, который оставил после себя {link:flight-from-eldre-thalas}Шал'нан{/link}: совета, избранного самими {link:skyborne}шен'дорай{/link}. При нем этот порядок подвергся испытанию, какого еще не знал. Духи ушли, пилоны слабеют, культ Владыки Ветра держит половину острова, а два великих ордена его народа едва разговаривают друг с другом. Именно в его зале была раскрыта истинная цель культа, и именно его благословение отправило юных {link:zephras-isle}Зефрас{/link}а вниз, в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он возглавляет {link:shadow-council}Совет{/link} старейшин из {link:valanaar}Валанаар{/link}а.
• Он передал Миротворцам след, ведущий к культу: перебежчика из {link:al-aketh}Ал'Акет{/link}, который хотел перейти на их сторону.
• Он выслушал кристалл памяти, раскрывший замысел, который вынашивала {link:high-priestess-lorthuna}Лортуна{/link}.
• Он благословил походы обоих орденов в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни Верховного старейшины до этих дней написано мало. Ни одна летопись не сообщает, как давно Талаанис носит свой сан и кем был его племянник.]=],
		},
	},
	chapters = {
		{
			title = "Перстень рода Песни Теней",
			hint = [=[Принесите Верховному старейшине весть о западной сторожевой башне.]=],
			text = [=[Защитники западной сторожевой башни погибли на своем посту. Среди мертвых был племянник Верховного старейшины, и его родовой перстень вернулся в {link:valanaar}Валанаар{/link} в руке чужака. Талаанис принял перстень и весть с достоинством. Затем он сделал то, что в такие дни должен делать старейшина. Он отправил принесшего перстень к Миротворцам, ибо острову был нужен каждый меч, готовый служить.]=],
		},
		{
			title = "Кристалл памяти",
			hint = "Принесите Верховному старейшине то, что нес перебежчик.",
			text = [=[Перебежчик умер прежде, чем успел заговорить, но под его телом лежал поврежденный кристалл памяти. Талаанис велел, чтобы {link:valennia-stormfist}Валенния{/link} пробудила его. Из кристалла полились обрывки голосов: {link:high-priestess-lorthuna}Лортуна{/link} говорила о пилонах и об оберегах, которые должны пасть. Валенния вспомнила, как {link:flight-from-eldre-thalas}Шал'нан{/link} однажды сказал, что пилоны — не только якоря, но и обереги, щиты от всего прочего, что обитает в Небесной Выси. Талаанис понял все сразу. Культ хотел открыть остров своему Владыке Ветра.]=],
		},
		{
			title = "Судьба Зефраса",
			hint = [=[Расскажите Верховному старейшине, что стало известно на шпилях.]=],
			text = [=[После шпилей предводители обоих орденов пришли к старейшине с одной и той же мрачной вестью. Оберегов больше не было, и остров лежал открытым перед {link:al-akir}Ал'Акиром{/link}, в его собственном царстве. Каждый орден намеревался искать свой ответ в {link:azeroth}Азерот{/link}е, и Талаанис благословил оба. Он надеялся, что найденное ими принесет {link:zephras-isle}Зефрас{/link}у устойчивость, которой остров не знал уже много лет.]=],
		},
	},
	mentions = {
