		{ id = "aetheen-of-the-gales", name = "Этин Вихрей", note = "из того же совета" },
		{ id = "ayessa-dawnsinger", name = "Айесса Певица Зари", note = "Великая небесная провидица Ваятелей Ветра" },
		{ id = "elaadrin-evengale", name = "Элаадрин Вечерний Ветер", note = "Верховный магистр Высшего ордена" },
		{ id = "high-priestess-lorthuna", name = "Верховная жрица Лортуна", note = "хотела открыть его остров Владыке Ветра" },
	},
})

Translate("ruRU", "elaadrin-evengale", {
