			text = [=[Когда культ впервые прибег к насилию, Элаадрин советовал вести переговоры. Он отправил в святилище своего друга, магистра {link:belathaan-brightwish}Белатаан{/link}а. В {link:valanaar}Валанаар{/link} вернулась шкатулка, в которой лежал язык посланника, покрытый серебряной краской. Больше Элаадрин не хотел никаких бесед. Он предложил Миротворцам полную поддержку Высшего ордена.]=],
		},
		{
			title = "В оке бури",
			hint = [=[Встаньте рядом с Верховным магистром на шпилях над святилищем.]=],
			text = [=[На шпилях Элаадрин предложил жрице Лортуне быструю смерть, если она сдастся. Она рассмеялась ему в лицо. Когда явился слуга Владыки Ветра, Элаадрин мало что мог противопоставить ему, кроме собственной отваги, пока не прибыли маги {link:kirin-tor}Кирин-Тор{/link}а, и тогда он впервые приветствовал верховного мага {link:archmage-ansirem-runeweaver}Ансирема Ткача Рун{/link}.]=],
		},
		{
			title = "Небесный корабль в Даларан",
			hint = "Отплывите из Валанаара в город магов.",
			text = [=[Элаадрин хотел первым из своего народа ступить на землю {link:azeroth}Азерот{/link}а. Культ изменил его планы. Пока он остается в {link:valanaar}Валанаар{/link}е и отправляет юных магистров вперед, в {link:dalaran}Даларан{/link}, где их ждет один из его магов.]=],
		},
	},
	mentions = {
