		{ text = "На службе {link:zephras-isle}Зефрас{/link}а" },
		{ text = "Поручение Филлиона" },
		{ text = "Судьба {link:zephras-isle}Зефрас{/link}а" },
		{ text = "Что будет дальше" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Айесса Певица Зари", note = "его соперница, пока что союзница" },
		{ id = "belathaan-brightwish", name = "Белатаан Светлое Желание", note = "его друг и посланник" },
		{ id = "rathiril-sunlance", name = "Ратирил Солнечное Копье", note = "старейшина его ордена в Шен'даре" },
		{ id = "valennia-stormfist", name = "Валенния Кулак Бури", note = "капитан, за которой он согласился идти" },
		{ id = "high-priestess-lorthuna", name = "Верховная жрица Лортуна", note = "жрица, с которой он сражался на шпилях" },
		{ id = "talaanis-shadowsong", name = "Талаанис Песнь Теней", note = "Верховный старейшина острова Зефрас" },
	},
})

Translate("ruRU", "ayessa-dawnsinger", {
	title = "Айесса Певица Зари",
	subtitle = "Великая небесная провидица Ваятелей Ветра",
