	hint = [=[Найдите Великую небесную провидицу в обители Ваятелей Ветра в Валанааре.]=],
	allegiance = "Ваятели Ветра · Орда",
	aliases = { "Айесса", "Великая небесная провидица" },
	sections = {
		{
			title = "Обзор",
			text = [=[Айесса Певица Зари — Великая небесная провидица {link:windshapers}Ваятелей Ветра{/link}, шаманов и провидцев острова {link:zephras-isle}Зефрас{/link}. Она неистова, горда и скора на гнев и ревниво оберегает свой титул и священные места своего ордена. Она верит, что ее народ должен призвать пропавших духов домой, и в поисках их она нашла {link:earthen-ring}Служителей Земли{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Айесса — голос тех {link:skyborne}шен'дорай{/link}, что все еще хранят верность духам ветра. Она не отрицает беды. Она открыто говорит, что {link:windshapers}Ваятели Ветра{/link}, возможно, разделяют вину за уход духов, и называет {link:al-aketh}Ал'Акет{/link} темным зеркалом собственного ордена. Обыскивая планы своим небесным зрением, она наткнулась на шаманов {link:azeroth}Азерота{/link}, чей взор проникал за пределы небес. Через шамана {link:muln-earthfury}Мулн{/link}а Гнева Земли Ваятели Ветра пришли к Служителям Земли, а через Служителей — в {link:horde}Орду{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она руководит Ваятелями Ветра из их обители в {link:valanaar}Валанаар{/link}е.
• Она послала послушника наказать магистра {link:belathaan-brightwish}Белатаан{/link}а из Высшего ордена за то, что он посягнул на конструкты духов.
• Она требует крови за кровь, когда убивают членов ее ордена.
• Она послала за Служителями Земли перед приступом святилища.
• На шпилях {link:rohash}Рохаш{/link}и она встала против жрицы Лортуны, некогда своей сестры по ордену.]=],
		},
	},
	chapters = {
		{
			title = "Великое приключение",
			hint = [=[Выслушайте замысел Великой небесной провидицы о будущем Ваятелей Ветра.]=],
			text = [=[Айесса рассказала юным Ваятелям Ветра о том, что нашла. Колыбель их народа, {link:kalimdor}Калимдор{/link}, теперь была частью гораздо большего мира. Его шаманы были могущественнее любого на {link:zephras-isle}Зефрас{/link}е, и их знание планов могло спасти остров. Она призвала сильных юных {link:skyborne}шен'дорай{/link} присоединиться к походу к ним.]=],
		},
		{
			title = "Сломанный конструкт",
