		{
			title = "Передовой отряд",
			hint = "Отплывите из Валанаара в землю Служителей Земли.",
			text = [=[Айесса хотела сама отправиться в {link:azeroth}Азерот{/link}. Культ удержал ее в {link:valanaar}Валанаар{/link}е. Вместо этого она посылает вперед горстку юных Ваятелей Ветра как свой передовой отряд — в {link:mulgore}Мулгор{/link}, где ждет {link:alaana-stormwalker}Алаана Странница Бурь{/link}. Она поклялась, что ее народ найдет способ спасти свой дом.]=],
