		{ id = "elaadrin-evengale", name = "Элаадрин Вечерний Ветер", note = "ее соперник, пока что союзник" },
		{ id = "high-priestess-lorthuna", name = "Верховная жрица Лортуна", note = "некогда ее сестра по ордену Ваятелей Ветра" },
