Translate("ruRU", "al-akir", {
	title = "Ал'Акир",
	subtitle = "Владыка Ветра, повелитель Небесной Выси",
	found = "Где-то среди бесконечных бурь Небесной Выси",
	allegiance = "Стихийный план",
	aliases = { "Ал'Акир Владыка Ветра", "Владыка Ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ал'Акир, Владыка Ветра, — повелитель воздуха и хозяин {link:skywall}Небесной Выси{/link}. Он один из четырех великих повелителей стихий, равный им: {link:ragnar-thunderbrew}Рагнар{/link}осу, владыке огня, Нептулону, владыке приливов, и Теразан, владычице камня. Ветер и буря — его слуги, а элементали воздуха — его воинство. Ни одна летопись смертных не говорит о ком-либо, кто предстал перед ним и вернулся.]=],
		},
		{
			title = "Значение",
			text = [=[Для {link:elements}повелителей стихий{/link} смертные народы значат мало. Владыка Ветра не знал, что {link:skyborne}шен'дорай{/link} существуют. Десять тысяч лет духи его собственного царства скрывали {link:zephras-isle}остров Зефрас{/link} от его взора за оберегами пилонов, и эльфы выросли в его владениях, не зная его. Духи, воспитавшие их, не желали произносить его имя. Когда эльфы спрашивали, духи тревожились, уходили от ответа и говорили, что на своих островах им нечего бояться. Некоторые шен'дорай начали сомневаться, что он существует. Другие, глядя через план своим небесным зрением, мельком увидели его мощь и стали ей поклоняться.]=],
		},
		{
			title = "Деяния",
			text = [=[• В первую эпоху мира он и другие повелители стихий служили Древним богам, пока слуги титанов не заточили элементалей в особом царстве.
• Он правит Небесной Высью с воинством элементалей воздуха и владык ветров.
• Его имени поклоняются {link:al-aketh}Ал'Акет{/link}, которые называют себя его верными.
• Его проповедники предупреждают, что всякий, кто придет к его верным с обманом, познает его гнев.
• Его слуга {link:rohash}Рохаш{/link} похваляется, что войскам Владыки Ветра в Небесной Выси нет конца.
• Страх перед его приходом ныне гонит оба ордена {link:skyborne}шен'дорай{/link} искать помощи в {link:azeroth}Азероте{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этой эпохи не описывает ни лика Владыки Ветра, ни его престола в Небесной Выси, ни его воли. Шен'дорай знают его лишь по молчанию своих духов и по похвальбе его слуг.]=],
		},
	},
	chapters = {
		{
			title = "Взор Владыки Ветра",
			hint = [=[Узнайте, что Служители Земли и Кирин-Тор рассказали орденам о Владыке Ветра.]=],
			text = [=[Когда {link:high-priestess-lorthuna}Лортуна{/link} зажгла свой маяк на шпилях {link:rohash}Рохаш{/link}и, на него откликнулся Рохаш, Владыка Восточного Ветра. Он был поражен тем, что подобное место может существовать в царстве Владыки Ветра, и похвалил своих «заблудших братьев» за то, что они так хорошо его спрятали. Он пообещал, что его господин услышит об этом. Шаманы Служителей Земли и маги {link:kirin-tor}Кирин-Тор{/link}а рассказали эльфам то, что знали о повелителях стихий. Услышанное дало предводителям обоих орденов веские причины для страха. В собственных владениях Ал'Акир мог уничтожить их, когда пожелает.]=],
		},
	},
	mentions = {
		{
			text = [=[Следующий шаг, где старейшина называет его мнимым правителем Небесной Выси]=],
		},
		{ text = "Деревня Фалаат, призыв культа служить ему" },
	},
	bonds = {
		{ id = "rohash", name = "Рохаш", note = "Владыка Восточного Ветра, его слуга" },
		{ id = "high-priestess-lorthuna", name = "Верховная жрица Лортуна", note = "зажгла маяк во имя его" },
		{ id = "ayessa-dawnsinger", name = "Айесса Певица Зари", note = "страшится его суда" },
	},
})

Translate("ruRU", "valennia-stormfist", {
	title = "Валенния Кулак Бури",
	subtitle = "Капитан Миротворцев",
	found = "Зал совета в Валанааре",
	hint = "Ищите капитана Миротворцев в зале совета в Валанааре.",
	allegiance = "Миротворцы · остров Зефрас",
	aliases = { "Валенния" },
	sections = {
		{
			title = "Обзор",
			text = [=[Валенния Кулак Бури — капитан {link:peacekeepers}Миротворцев{/link}, ополчения острова {link:zephras-isle}Зефрас{/link}. Она поддерживает порядок в {link:valanaar}Валанаар{/link}е и запрещает Ваятелям Ветра и Высшему ордену драться на своих улицах. Она прямолинейна и практична. Долгое время ее Миротворцы избегали открытой войны с культом. Когда это стало невозможно, именно она составила план этой войны.]=],
		},
		{
			title = "Значение",
			text = [=[Валенния стоит между двумя враждующими орденами острова и культом, который угрожает обоим. Она увидела, что {link:windshapers}Ваятели Ветра{/link} и {link:high-order}Высший орден{/link} никогда не объединятся ради друг друга. Но они могли объединиться против большего врага. Ее план приступа Святилища Акира, подготовленный задолго до того, как он понадобился, вывел в поле все три силы разом.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она командует Миротворцами из {link:valanaar}Валанаар{/link}а.
• Она послала подмогу к восточной сторожевой башне, когда культ напал на нее.
• Она пробудила кристалл памяти перебежчика и вспомнила, что пилоны были еще и оберегами.
• Она заручилась поддержкой обоих орденов для приступа святилища.
• Она прорвалась во внутреннее святилище Святилища Акира.]=],
		},
	},
	chapters = {
		{
			title = "Отчаянные времена",
			hint = "Отнесите план капитана предводителям обоих орденов.",
			text = [=[Культ властвовал над большей частью острова и считал Миротворцев разбитыми. Валенния намеревалась обратить эту гордыню против него. Отвлекающий удар перед святилищем и малый отряд из Миротворцев, Ваятелей Ветра и магистров, идущий вверх по флангу, могли достичь внутреннего святилища и покончить с жрицей Лортуной там. Оба ордена согласились. Ни один не простил другого.]=],
		},
		{
			title = "Внутреннее святилище",
			hint = "Следуйте за силами капитана в сердце святилища.",
			text = [=[Бой в святилище был яростным, а затем наступила странная тишина. Силы капитана удержали его, израненные и поредевшие. {link:high-priestess-lorthuna}Лортуна{/link} бежала через портал на шпили наверху, и предводители обоих орденов пустились за ней. Валенния, слишком тяжело раненная, чтобы идти следом, послала других им на помощь.]=],
		},
	},
	mentions = {
		{ text = "В {link:valanaar}Валанаар{/link}" },
		{ text = "Оборона башни" },
		{ text = "Жучок" },
		{ text = "Готовьтесь к битве" },
		{ text = "Лицом к лицу с Лортуной" },
	},
	bonds = {
		{ id = "talaanis-shadowsong", name = "Талаанис Песнь Теней", note = "Верховный старейшина, которому она служит" },
		{ id = "constable-aonda", name = "Констебль Аонда", note = "хранит покой в Шен'даре" },
		{ id = "yorana-windyreed", name = "Йорана Ветреный Тростник", note = "ее лейтенант" },
		{ id = "hyusaa-quickbreeze", name = "Хьюсаа Быстрый Ветерок", note = "ее заместитель у святилища" },
		{ id = "high-priestess-lorthuna", name = "Верховная жрица Лортуна", note = "враг, за которым она охотилась" },
	},
})

Translate("ruRU", "aetheen-of-the-gales", {
	title = "Этин Вихрей",
	subtitle = "Старейшина острова Зефрас",
	found = "деревня Тендал",
	hint = [=[Ищите старейшину совета, которая присматривает за юными в деревне Тендал.]=],
	allegiance = "Совет старейшин · остров Зефрас",
	aliases = { "Этин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Этин Вихрей — член {link:shadow-council}Совет{/link}а старейшин острова {link:zephras-isle}Зефрас{/link}. Она пришла в деревню Тендал, чтобы читать течение ветров в роще и оценивать юных {link:skyborne}шен'дорай{/link}, которые достигают там совершеннолетия. Она сначала наблюдает, а потом говорит. К тому времени, как юноша или девушка встречается с ней, она уже очень многое о них знает.]=],
		},
		{
			title = "Значение",
			text = [=[Этин — око совета, обращенное на следующее поколение. Во времена, когда острову нужна каждая умелая рука, она решает, кто из юных готов покинуть убежище рощи. Она же одной из первых прямо называет им опасность: {link:al-aketh}Ал'Акет{/link}, фанатики «мнимого» правителя Небесной Выси, чьи сила и притязания растут с каждым днем.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она читает ветра Рощи Тендал для совета.
• Она испытывает юных, посылая их против урсер и матери их логова.
• Она посылает их на юг, к констеблю Аонде в деревню Шен'дар, которой угрожает культ.
• Других она посылает учиться обычаям дикой природы у странника близ Шен'дара.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни старейшины до этих дней написано мало. Не записано, принадлежит ли Этин к одному из орденов и как давно она заседает в совете.]=],
		},
	},
	chapters = {
		{
			title = "Следующий шаг",
			hint = [=[Пройдите испытание старейшины и идите туда, куда она вас пошлет.]=],
			text = [=[В пещерах к югу от рощи урсеры оголодали и отчаялись; вела их мать логова, которую следопыты прозвали Урс'ана. Этин послала туда юных, чтобы испытать их решимость. Когда испытание было пройдено, она не стала долго их хвалить. Она отправила их на юг, где культ теснил деревню Шен'дар, и велела сказать, что их прислала она.]=],
		},
	},
	mentions = {
		{ text = "Этин Вихрей" },
		{ text = "Мерзкая матриарх" },
		{ text = "Искатель приключений" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Рориан Искатель Дня", note = "посылает к ней юных" },
		{ id = "constable-aonda", name = "Констебль Аонда", note = "достойная женщина, по ее словам" },
		{ id = "talaanis-shadowsong", name = "Талаанис Песнь Теней", note = "Верховный старейшина ее совета" },
	},
})

Translate("ruRU", "high-priestess-lorthuna", {
	title = "Верховная жрица Лортуна",
	subtitle = "Верховная жрица Ал'Акет",
	found = "Святилище Акира и шпили над ним",
	hint = "Сразитесь с верховной жрицей культа Владыки Ветра.",
	allegiance = "Ал'Акет",
	aliases = { "Лортуна" },
	sections = {
		{
			title = "Обзор",
			text = [=[Верховная жрица Лортуна возглавляет {link:al-aketh}Ал'Акет{/link} — культ на острове {link:zephras-isle}Зефрас{/link}, поклоняющийся {link:al-akir}Ал'Акиру{/link}. Когда-то она принадлежала к Ваятелям Ветра и была сестрой по ордену для Айессы Певицы Зари. Теперь она правит в {link:shrine-of-akir}Святилище Акира{/link} и говорит о великом труде, который приведет Владыку Ветра к ее народу. Она холодна, умна и жестока, а ее последователи называют себя орудиями ее воли.]=],
		},
		{
			title = "Значение",
			text = [=[Лортуна увидела то, чего не видел остальной ее народ: пилоны {link:zephras-isle}Зефрас{/link}а были не только якорями, но и оберегами. Она превратила эту тайну в оружие. Ее культ захватил деревню Фалаат, ударил по сторожевым башням у пилонов и обрушил обереги. Что бы с ней ни сталось, сделанного ею не исправить. Зефрас теперь лежит открытым перед своим Владыкой Ветра.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она рассылала налетчиков и проповедников по всему острову из Святилища Акира.
• Она встретилась в Фалаате с небесным жрецом {link:skypriest-aanders}Аандерс{/link}ом и привела в движение свои удары по Шен'дару и западной сторожевой башне.
• Она приказала убить посланника Высшего ордена {link:belathaan-brightwish}Белатаан{/link}а {link:holy-light}Свет{/link}лого Желания и отослала его язык в {link:valanaar}Валанаар{/link}.
• Она зажгла на шпилях {link:rohash}Рохаш{/link}и маяк для слуг Владыки Ветра.]=],
		},
	},
	chapters = {
		{
			title = "Гостья в Фалаате",
			hint = "Узнайте, что культ замышляет против Нагорья Шен'дар.",
			text = [=[Новобранцу, который пришел к верным в Фалаат, велели держаться подальше от постоялого двора, где небесный жрец принимал гостью. Гостьей была Лортуна. Ее приказы были кратки. У нее были другие дела, а это была лишь одна фигура в ее игре. {link:skypriest-aanders}Аандерс{/link} возьмет западную сторожевую башню, а Циклас возьмет деревню Шен'дар.]=],
		},
		{
			title = "Маяк",
			hint = "Следуйте за верховной жрицей на шпили над ее святилищем.",
			text = [=[На шпилях Лортуна сказала своим врагам, что они опоздали. Обереги пали уже несколько дней назад. Она зажигала маяк. Когда явился Владыка Восточного Ветра, она приветствовала его и попросила привести ее к Владыке Ветра как вестницу его славы. {link:rohash}Рохаш{/link} отшвырнул ее ударом, и она улетела в бескрайнее небо.]=],
		},
	},
	mentions = {
		{ text = "Головорезы {link:al-aketh}Ал'Акет{/link}" },
		{ text = "Десятикратное отмщение" },
		{ text = "Истинные замыслы культа" },
	},
	bonds = {
