Translate("ruRU", "windshapers", {
	title = "Ваятели Ветра",
	aliases = { "Ваятель Ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ваятели Ветра — шаманы и провидцы народа {link:skyborne}Рожденных Небом{/link}. Они происходят от первых шен'дорай, получивших от духов ветра дар небесного зрения — способность видеть через весь план стихий. Веками они были духовными наставниками острова {link:zephras-isle}Зефрас{/link}. Они охраняют его священные стоячие камни и присматривают за конструктами и орудиями, которые оставили после себя духи.]=],
		},
		{
			title = "Их вера",
			text = [=[Ваятели Ветра считают, что их народ в долгу перед духами ветра и что этот долг никогда не будет выплачен сполна. Они поклялись найти духов и возродить старые обычаи. Без духов, говорят они, они почти слепы к тому, что происходит в {link:skywall}Небесной Выси{/link}. Некоторые из них боятся, что в уходе духов виноваты они сами. Они не доверяют {link:high-order}Высшему ордену{/link}, который называют надменными наследниками высокорожденных, стремящимися подчинить то, что следует чтить. Там, где Высший орден видит в поднявшихся силовых линиях дар, Ваятели Ветра видят раны на теле земли.]=],
		},
		{
			title = "В наши дни",
			text = [=[Их магия угасает с тех пор, как ушли духи, и между ними и Высшим орденом лежит кровь. Их предводительница, {link:ayessa-dawnsinger}Великая небесная провидица{/link} Айесса Певица Зари, обыскала планы своим небесным зрением и нашла {link:earthen-ring}Служителей Земли{/link} в {link:azeroth}Азероте{/link}. Через Служителей Земли Ваятели Ветра вступили в {link:horde}Орду{/link}. Их передовой отряд теперь плывет из {link:valanaar}Валанаар{/link}а в {link:mulgore}Мулгор{/link}.]=],
		},
	},
})

Translate("ruRU", "high-order", {
	title = "Высший орден",
	sections = {
		{
			title = "Обзор",
			text = [=[Высший орден — магистры народа {link:skyborne}Рожденных Небом{/link}, потомки ученых-высокорожденных из Эльдре'Таласа. Они называют себя хранителями обычаев высокорожденных. За десять тысяч лет в {link:skywall}Небесной Выси{/link} многое из их тайных знаний было забыто, а их сила пошла на убыль. Они намерены ее вернуть.]=],
		},
		{
			title = "Их вера",
			text = [=[Высший орден считает, что {link:skyborne}шен'дорай{/link} совершили тяжкую ошибку, когда отдали свою судьбу в руки переменчивых духов. Исчезновение духов это доказало. То, что некогда делали духи, верит орден, можно сделать магией {red:highborne}высокорожденных{/red}, и остров сможет стоять сам по себе. Они изучают поднявшиеся силовые линии {link:zephras-isle}Зефрас{/link}а и стихийную магию стоячих камней, что бы ни говорили {link:windshapers}Ваятели Ветра{/link}. Для Ваятелей Ветра они — назойливые незваные гости. Для самих себя они — единственные, кто готов действовать.]=],
		},
		{
			title = "В наши дни",
			text = [=[Верховный магистр {link:elaadrin-evengale}Элаадрин Вечерний Ветер{/link} нашел способ заглянуть сквозь планы и обнаружил, что в ответ на него смотрит {link:kirin-tor}Кирин-Тор{/link} из {link:dalaran}Даларана{/link}. Через Кирин-Тор Высший орден вступил в {link:alliance}Альянс{/link}. Его юные магистры теперь плывут из {link:valanaar}Валанаар{/link}а в Даларан, чтобы вернуть знания, утраченные их предками.]=],
		},
	},
})

Translate("ruRU", "al-aketh", {
	title = "Ал'Акет",
	aliases = { "культ Ал'Акет", "культ Ал'Акира" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ал'Акет — культ {link:skyborne}шен'дорай{/link}, которые поклоняются Владыке Ветра {link:al-akir}Ал'Акиру{/link}. Некоторые из его основателей с помощью небесного зрения заглянули через всю {link:skywall}Небесную Высь{/link} и мельком увидели ужасающую мощь ее хозяина. Соблазненные этой силой, они порвали со своим народом и отдали себя ему на службу. Когда исчезли {link:vanishing-of-the-wind-spirits}духи ветра{/link}, культ поднялся на страхе, который за этим последовал.]=],
		},
		{
			title = "Их вера",
			text = [=[Культ проповедует, что {link:skyborne}шен'дорай{/link} стали горды и праздны, принимая дары ветров как должное, и что духи покинули их за это. Только покаяние и служение Владыке Ветра вернут ветер. Его проповедники изображают кроткую веру. Его громилы, заклинатели бурь и убийцы делают все остальное. Многие из его членов прежде принадлежали к Ваятелям Ветра, к Миротворцам или были друидами, и {link:ayessa-dawnsinger}Айесса Певица Зари{/link} называет культ темным зеркалом собственного ордена.]=],
		},
		{
			title = "В наши дни",
			text = [=[При Верховной жрице Лортуне культ удерживал деревню Фалаат и {link:shrine-of-akir}Святилище Акира{/link}, грабил караваны острова и бил по сторожевым башням у пилонов, чтобы обрушить обереги, скрывавшие {link:zephras-isle}Зефрас{/link}. Его верховной жрицы больше нет, а его святилище взято приступом, но его цель достигнута. Слуги Владыки Ветра теперь знают, где лежит Зефрас.]=],
		},
	},
})

Translate("ruRU", "peacekeepers", {
	title = "Миротворцы",
	aliases = { "Миротворец" },
	sections = {
		{
			title = "Обзор",
			text = [=[Миротворцы — ополчение острова {link:zephras-isle}Зефрас{/link} и самое близкое к войску, что есть у народа {link:skyborne}Рожденных Небом{/link}. Они подчиняются капитану Валеннии Кулак Бури в {link:valanaar}Валанаар{/link}е и {link:shadow-council}Совет{/link}у старейшин. Их констебли поддерживают порядок в селениях, а их солдаты несут службу на сторожевых башнях, охраняющих {link:anchor-pylons}якорные пилоны{/link}.]=],
		},
		{
			title = "В наши дни",
			text = [=[Долгое время Миротворцы избегали открытой войны с {link:al-aketh}Ал'Акет{/link}, надеясь, что культ останется лишь досадной помехой. Эта надежда кончилась у деревни Шен'дар и у сторожевых башен при пилонах. Малочисленные, они сражались с культом по всему острову и возглавили приступ Святилища Акира. Они же стоят между {link:windshapers}Ваятелями Ветра{/link} и {link:high-order}Высшим орденом{/link}, и их капитан не потерпит, чтобы два ордена дрались в {link:valanaar}Валанаар{/link}е. Не все они остались верны. {link:commander-belguilos}Белгилос{/link}, которую культ теперь зовет Сокрушительницей, когда-то носила их цвета. Среди тех, кто выстоял, были констебль {link:constable-aonda}Аонда{/link} из Шен'дара, лейтенант {link:yorana-windyreed}Йорана Ветреный Тростник{/link} у восточной башни и {link:hyusaa-quickbreeze}Хьюсаа Быстрый Ветерок{/link}, заместитель капитана.]=],
		},
	},
})

Translate("ruRU", "anchor-pylons", {
	title = "Якорные пилоны",
	aliases = { "якорный пилон", "якорные пилоны", "пилоны ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Якорные пилоны — древние башни стихийной магии, дары духов ветра народу {link:skyborne}шен'дорай{/link}. Они скрепляют {link:zephras-isle}остров Зефрас{/link} и удерживают его на месте в {link:skywall}Небесной Выси{/link}. Рядом с ними стоят сторожевые башни Миротворцев: одна в западных нагорьях, другая у самого {link:valanaar}Валанаар{/link}а.]=],
		},
		{
			title = "Их упадок",
			text = [=[С тех пор как исчезли духи, пилоны стали неустойчивыми. Их великолепие не изменилось, и никаких повреждений не видно, но их магия дает сбои. По мере того как она слабеет, части острова осыпаются и падают в небо. Шен'дорай теперь прибегают к камням ветра для повседневных нужд, а {link:high-order}Высший орден{/link} надеется овладеть магией пилонов прежде, чем она иссякнет окончательно.]=],
		},
		{
			title = "Обереги",
			text = [=[Шен'дорай наполовину забыли о втором их назначении. Пилоны — это еще и обереги. Они заслоняли остров от взора всего прочего, что обитает в Небесной Выси. {link:flight-from-eldre-thalas}Шал'нан{/link} однажды говорил об этом, и {link:al-aketh}Ал'Акет{/link} это узнали. Они ударили по пилонам, чтобы обрушить обереги, и преуспели. {link:zephras-isle}Зефрас{/link} все еще парит, но он больше не скрыт.]=],
		},
	},
})

Translate("ruRU", "vanishing-of-the-wind-spirits", {
	title = "Исчезновение духов ветра",
	aliases = { "духи ветра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тысячи лет духи ветра жили на острове {link:zephras-isle}Зефрас{/link} рядом с {link:skyborne}шен'дорай{/link} — как покровители, учителя и друзья. Они подняли остров, заботились о его магии и дали его провидцам небесное зрение. Затем, несколько веков назад, они исчезли. Они ни о чем не предупредили, и никто на Зефрасе не знает, почему они ушли и куда.]=],
		},
		{
			title = "Что было потом",
			text = [=[Магия острова начала угасать. {link:anchor-pylons}Якорные пилоны{/link} стали давать сбои. Большинство конструктов духов перестало работать. В лесу Теневого Шквала появились странные бледные духи, которых зовут пустыми. Звери одичали, а малые духи ветра стали впадать в ярость, если их потревожить. Связь с другими островами была утрачена, и целые селения упали в небо. Каждая сторона истолковала утрату по-своему. {link:windshapers}Ваятели Ветра{/link} хотят найти духов и призвать их домой. {link:high-order}Высший орден{/link} говорит, что эльфы никогда больше не должны от них зависеть. {link:al-aketh}Ал'Акет{/link} проповедуют, что духи покинули гордый народ и что остался лишь {link:al-akir}Владыка Ветра{/link}.]=],
		},
	},
})

Translate("ruRU", "flight-from-eldre-thalas", {
	title = "Бегство из Эльдре'Таласа",
	aliases = { "Восстание в Эльдре'Таласе", "Шал'нан" },
	sections = {
		{
			title = "Обзор",
			text = [=[{link:skyborne}Рожденные Небом{/link} начинали как мятежники. После {link:war-of-the-ancients}Войны древних{/link} {red:highborne}высокорожденные{/red} из Эльдре'Таласа — города в {link:feralas}Фераласе{/link}, который ныне зовется {red:dire-maul}Забытым Городом{/red}, — остались без Источника, питавшего их магию. Принц {red:tortheldrin}Тортелдрин{/red} стремился поддержать их силами все более темными. Некоторые из его подданных видели, куда ведет такой голод, и не желали допустить, чтобы ошибки королевы Азшары повторились.]=],
		},
		{
			title = "Скрытый под покровом",
			text = [=[Мятежников вел тот, кого знали лишь как Шал'нана, Скрытого под покровом; он прятал лицо за гладкой золотой маской без черт. Его имя стало боевым кличем. Вредительством и кое-чем похуже его последователи мешали работе сети кристальных средоточий принца и раз за разом покрывали его позором. В те дни по городу распространялся и друидизм {link:night-elves}ночных эльфов{/link} севера, и принц осуждал его как низменный. Мятежники приняли последний бой в его святилище. Худшее они предотвратили, но большинство из них погибло.]=],
		},
		{
			title = "Бегство",
			text = [=[Выжившие бежали на запад, а за ними шел флот принца. За морем они нашли землю, которой правили древние духи, и там заключили свой договор с ветром. Духи подняли эту землю в {link:skywall}Небесную Высь{/link}, и изгнанники стали {link:skyborne}шен'дорай{/link} — сокрытым народом. Со временем Шал'нан сложил с себя власть и передал ее совету, избранному его народом.]=],
		},
	},
})
